/**
 * Homepage map-section cards.
 * Story Studio: swap ROUTE_MAPS_CARD_ART when the final route-card art is ready.
 * The history-map card art is generated by scripts/build-history-map-card.mjs.
 */
import { HISTORY_MAP_CARD } from './history-map-card.generated.js'

export const ROUTE_MAPS_CARD_ART =
  '/maps/routes/athiamiowee-the-warriors-path-through-kentucky/warriors-path-home-card'

export const ROUTE_MAPS_CARD_WIDTH = 640
export const ROUTE_MAPS_CARD_HEIGHT = 400

const ROUTE_MAPS_CARD = {
  light: `${ROUTE_MAPS_CARD_ART}-light.webp`,
  dark: `${ROUTE_MAPS_CARD_ART}-dark.webp`,
  type: 'image/webp',
  width: ROUTE_MAPS_CARD_WIDTH,
  height: ROUTE_MAPS_CARD_HEIGHT,
}

function paintPicture(picture, art) {
  const source = picture?.querySelector('source')
  const img = picture?.querySelector('img')
  if (!source || !img) return
  const theme = document.documentElement.getAttribute('data-hp-theme') === 'light' ? 'light' : 'dark'
  const osDark = window.matchMedia?.('(prefers-color-scheme: dark)').matches
  source.type = art.type
  source.srcset = art.dark
  if ((theme === 'dark') === !!osDark) source.media = '(prefers-color-scheme: dark)'
  else if (theme === 'dark') source.media = '(min-width: 0px)'
  else source.media = 'not all'
  img.src = art.light
  img.width = art.width
  img.height = art.height
  img.alt = ''
  img.loading = 'lazy'
  img.decoding = 'async'
  img.remove()
  picture.appendChild(img)
}

/** Point both homepage map cards at their light and dark art. */
export function paintHomeMapCards(root = document) {
  paintPicture(root.querySelector?.('a.hp-history-map picture'), HISTORY_MAP_CARD)
  paintPicture(root.querySelector?.('a.hp-map-routes picture'), ROUTE_MAPS_CARD)
}

export function paintRouteMapsCard(root = document) {
  paintHomeMapCards(root)
}
